mapper.select:


    and s.country = #{country}
    and c.status = #{status}
    and (s.school_name like concat('%', #{schoolName}, '%') or s.school_name_en ilike concat('%', #{schoolName}, '%'))

order by s.country, s.school_name_en


where c.status = '0' and (c.last_discover_time is null or c.last_discover_time < #{before})
  and s.country in #{x}
order by c.last_discover_time nulls first, c.site_id

mapper.update:
update abr_crawl_site
set sitemaps = cast(#{sitemaps} as jsonb), crawl_delay = #{crawlDelay}, last_discover_time = now(), last_discover_result = #{result}, update_time = now()
where site_id = #{siteId}

mapper.select:


    and p.school_id = #{schoolId}
    and p.site_id = #{siteId}
    and p.status = #{status}
    and p.kind = #{kind}
    and p.url ilike concat('%', #{url}, '%')

order by p.update_time desc nulls last, p.page_id desc
